import{_ as i,c as a,o,a2 as t}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/usage.md","filePath":"zh-CN/guide/usage.md","lastUpdated":1793163976000}'),r={name:"zh-CN/guide/usage.md"};function e(n,l,d,s,h,g){return o(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to &quot;使用指南&quot;">​</a></h1><h2 id="打开归档" tabindex="-1">打开归档 <a class="header-anchor" href="#打开归档" aria-label="Permalink to &quot;打开归档&quot;">​</a></h2><h3 id="双击打开" tabindex="-1">双击打开 <a class="header-anchor" href="#双击打开" aria-label="Permalink to &quot;双击打开&quot;">​</a></h3><p>NueZip 会注册为所有受支持归档格式的默认处理程序。只需双击任意归档文件（<code>.zip</code>、<code>.rar</code>、<code>.7z</code>、<code>.tar</code>、<code>.gz</code>、<code>.bz2</code>、<code>.xz</code>、<code>.zst</code>）即可在 NueZip 主窗口中打开它。</p><h3 id="使用-nuezip-打开-finder-上下文菜单" tabindex="-1">使用 NueZip 打开（Finder 上下文菜单） <a class="header-anchor" href="#使用-nuezip-打开-finder-上下文菜单" aria-label="Permalink to &quot;使用 NueZip 打开（Finder 上下文菜单）&quot;">​</a></h3><p>右键点击任意归档文件，并从上下文菜单中选择 <strong>使用 NueZip 打开</strong>。Finder 扩展还提供快速操作：</p><ul><li><strong>解压到此</strong> — 将归档内容解压到当前文件夹</li><li><strong>解压到 &quot;文件夹名/&quot;</strong> — 解压到指定名称的子文件夹</li><li><strong>压缩为 ZIP</strong> — 将选中的文件/文件夹压缩为 ZIP 归档</li><li><strong>使用 NueZip 打开</strong> — 在主浏览窗口中打开</li></ul><h3 id="拖放到托盘" tabindex="-1">拖放到托盘 <a class="header-anchor" href="#拖放到托盘" aria-label="Permalink to &quot;拖放到托盘&quot;">​</a></h3><p>将任意归档文件拖到 NueZip 的菜单栏图标上，即可在放置面板中快速打开它以便即时访问。你也可以将文件拖到托盘图标上以压缩它们。</p><h2 id="解压归档" tabindex="-1">解压归档 <a class="header-anchor" href="#解压归档" aria-label="Permalink to &quot;解压归档&quot;">​</a></h2><h3 id="基本解压" tabindex="-1">基本解压 <a class="header-anchor" href="#基本解压" aria-label="Permalink to &quot;基本解压&quot;">​</a></h3><ol><li>在 NueZip 中打开一个归档</li><li>点击工具栏中的 <strong>解压</strong> 按钮</li><li>选择目标文件夹</li><li>点击 <strong>解压</strong></li></ol><h3 id="从-finder-快速解压" tabindex="-1">从 Finder 快速解压 <a class="header-anchor" href="#从-finder-快速解压" aria-label="Permalink to &quot;从 Finder 快速解压&quot;">​</a></h3><p>在 Finder 中右键点击归档，并选择以下快速操作之一：</p><ul><li><strong>解压到此</strong> — 直接解压到当前文件夹</li><li><strong>解压到 &quot;[归档名]/&quot;</strong> — 解压到指定名称的子文件夹以保持整洁</li></ul><h3 id="带密码解压" tabindex="-1">带密码解压 <a class="header-anchor" href="#带密码解压" aria-label="Permalink to &quot;带密码解压&quot;">​</a></h3><p>对于带密码保护的归档，NueZip 会提示输入密码。内置密码管理器可将凭据安全地存储在你本地的钥匙串中，以便日后使用。</p><h2 id="压缩归档" tabindex="-1">压缩归档 <a class="header-anchor" href="#压缩归档" aria-label="Permalink to &quot;压缩归档&quot;">​</a></h2><h3 id="创建新归档" tabindex="-1">创建新归档 <a class="header-anchor" href="#创建新归档" aria-label="Permalink to &quot;创建新归档&quot;">​</a></h3><ol><li>在 NueZip 主窗口中选择文件或文件夹</li><li>点击工具栏中的 <strong>压缩</strong> 按钮</li><li>选择归档格式（ZIP、7z、TAR、GZIP 等）</li><li>配置压缩设置（级别、加密方式）</li><li>点击 <strong>压缩</strong></li></ol><h3 id="从-finder-压缩" tabindex="-1">从 Finder 压缩 <a class="header-anchor" href="#从-finder-压缩" aria-label="Permalink to &quot;从 Finder 压缩&quot;">​</a></h3><p>在 Finder 中右键点击文件/文件夹，并选择 <strong>使用 NueZip 压缩</strong>：</p><ul><li><strong>压缩为 ZIP</strong> — 快速创建 ZIP 归档</li><li><strong>带选项压缩</strong> — 使用高级设置打开 NueZip</li></ul><h3 id="通过拖放压缩" tabindex="-1">通过拖放压缩 <a class="header-anchor" href="#通过拖放压缩" aria-label="Permalink to &quot;通过拖放压缩&quot;">​</a></h3><p>将文件拖到 NueZip 菜单栏托盘图标上，即可快速创建 ZIP 归档。</p><h2 id="批量操作" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作" aria-label="Permalink to &quot;批量操作&quot;">​</a></h2><h3 id="批量压缩" tabindex="-1">批量压缩 <a class="header-anchor" href="#批量压缩" aria-label="Permalink to &quot;批量压缩&quot;">​</a></h3><ol><li>在 NueZip 中选择多个项目</li><li>从工具栏或文件菜单中选择 <strong>批量压缩</strong></li><li>每个项目都会被压缩为独立的归档</li></ol><h3 id="批量解压" tabindex="-1">批量解压 <a class="header-anchor" href="#批量解压" aria-label="Permalink to &quot;批量解压&quot;">​</a></h3><ol><li>在 NueZip 中选择多个归档</li><li>从工具栏或文件菜单中选择 <strong>批量解压</strong></li><li>所有归档将同时被解压</li></ol><h3 id="批量转换" tabindex="-1">批量转换 <a class="header-anchor" href="#批量转换" aria-label="Permalink to &quot;批量转换&quot;">​</a></h3><ol><li>选择一个或多个归档</li><li>选择 <strong>转换</strong> → 选择目标格式</li><li>NueZip 会将每个归档重新压缩为所选格式</li></ol><h3 id="批量加密" tabindex="-1">批量加密 <a class="header-anchor" href="#批量加密" aria-label="Permalink to &quot;批量加密&quot;">​</a></h3><ol><li>选择多个 ZIP 归档</li><li>选择 <strong>批量加密</strong></li><li>设置密码 — 所有选中的归档都会被加上密码保护</li></ol><h2 id="格式转换" tabindex="-1">格式转换 <a class="header-anchor" href="#格式转换" aria-label="Permalink to &quot;格式转换&quot;">​</a></h2><p>在任意支持的格式之间转换归档：</p><ol><li>打开一个归档</li><li>点击工具栏中的 <strong>转换</strong></li><li>选择目标格式（例如，RAR → ZIP、7z → TAR.GZ）</li><li>选择输出位置</li><li>点击 <strong>转换</strong></li></ol><h2 id="归档修复" tabindex="-1">归档修复 <a class="header-anchor" href="#归档修复" aria-label="Permalink to &quot;归档修复&quot;">​</a></h2><p>对于损坏的 RAR 或 ZIP 归档：</p><ol><li>打开损坏的归档</li><li>点击工具栏中的 <strong>修复</strong></li><li>NueZip 会尝试重建归档数据</li><li>修复后的归档将另存为一个新文件</li></ol><h2 id="归档搜索" tabindex="-1">归档搜索 <a class="header-anchor" href="#归档搜索" aria-label="Permalink to &quot;归档搜索&quot;">​</a></h2><p>在归档中查找特定文件：</p><ol><li>点击工具栏中的 <strong>搜索</strong> 按钮</li><li>输入文件名模式</li><li>NueZip 会搜索打开归档中的所有条目</li><li>结果显示完整路径，便于快速导航</li></ol><h2 id="性能基准测试" tabindex="-1">性能基准测试 <a class="header-anchor" href="#性能基准测试" aria-label="Permalink to &quot;性能基准测试&quot;">​</a></h2><p>测试你系统的压缩性能：</p><ol><li>前往 <strong>工具 → 基准测试</strong></li><li>NueZip 会使用各种格式和设置运行压缩测试</li><li>结果展示每种格式的压缩速度（MB/s）和压缩比</li><li>可用此来比较不同压缩方法的性能</li></ol><h2 id="多卷-拆分-归档" tabindex="-1">多卷（拆分）归档 <a class="header-anchor" href="#多卷-拆分-归档" aria-label="Permalink to &quot;多卷（拆分）归档&quot;">​</a></h2><p>为大型数据创建拆分归档：</p><ol><li>在压缩过程中，启用 <strong>拆分为多卷</strong></li><li>选择卷大小（例如 100 MB、650 MB、4.7 GB，或自定义）</li><li>NueZip 会创建带编号的分卷文件（<code>.zip.001</code>、<code>.zip.002</code> 等）</li><li>要解压，请打开第一个分卷文件 — NueZip 会自动加载其余分卷</li></ol><ul><li><strong>密码</strong>：为加密归档提供密码</li><li><strong>包裹进文件夹</strong>：如果归档没有单一的根目录，自动创建一个根文件夹</li><li><strong>完成后打开</strong>：解压完成后在 Finder 中显示解压出的文件</li><li><strong>保留损坏的文件</strong>：保留错误发生前已解压的文件（用于部分恢复）</li><li><strong>更新模式</strong>：选择如何处理已有文件（覆盖、跳过、重命名）</li></ul><h3 id="批量解压-1" tabindex="-1">批量解压 <a class="header-anchor" href="#批量解压-1" aria-label="Permalink to &quot;批量解压&quot;">​</a></h3><ol><li>前往 <strong>工具 → 批量解压</strong></li><li>点击 <strong>添加文件...</strong> 选择归档文件</li><li>选择目标文件夹</li><li>（可选）启用 <strong>解压后删除源文件</strong></li><li>点击 <strong>开始</strong></li></ol><h2 id="创建归档" tabindex="-1">创建归档 <a class="header-anchor" href="#创建归档" aria-label="Permalink to &quot;创建归档&quot;">​</a></h2><h3 id="压缩文件" tabindex="-1">压缩文件 <a class="header-anchor" href="#压缩文件" aria-label="Permalink to &quot;压缩文件&quot;">​</a></h3><ol><li>点击工具栏中的 <strong>压缩</strong> 按钮</li><li>选择要压缩的文件（或将其拖放到窗口中）</li><li>选择 <strong>归档格式</strong>：ZIP、7Z、TAR、GZIP、BZIP2</li><li>配置 <strong>压缩方法</strong> 和级别</li><li>设置 <strong>保存位置</strong> 和归档名称</li><li>（可选）设置用于加密的 <strong>密码</strong></li><li>（可选）设置用于多卷归档的 <strong>拆分大小</strong></li><li>点击 <strong>压缩</strong></li></ol><h3 id="向已有归档添加文件" tabindex="-1">向已有归档添加文件 <a class="header-anchor" href="#向已有归档添加文件" aria-label="Permalink to &quot;向已有归档添加文件&quot;">​</a></h3><ol><li>在 NueZip 中打开一个已有归档</li><li>点击工具栏中的 <strong>添加文件</strong></li><li>选择要添加的文件</li><li>点击 <strong>添加</strong></li></ol><h2 id="批量操作-1" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作-1" aria-label="Permalink to &quot;批量操作&quot;">​</a></h2><h3 id="批量压缩-1" tabindex="-1">批量压缩 <a class="header-anchor" href="#批量压缩-1" aria-label="Permalink to &quot;批量压缩&quot;">​</a></h3><ol><li>前往 <strong>工具 → 批量压缩</strong></li><li>点击 <strong>选择文件/文件夹...</strong> 选择项目</li><li>每个选中的项目都会成为一个独立的归档</li><li>配置输出 <strong>格式</strong>、<strong>保存位置</strong> 和文件命名前缀</li><li>点击 <strong>开始</strong></li></ol><h3 id="批量转换格式" tabindex="-1">批量转换格式 <a class="header-anchor" href="#批量转换格式" aria-label="Permalink to &quot;批量转换格式&quot;">​</a></h3><ol><li>前往 <strong>工具 → 批量转换格式</strong></li><li>点击 <strong>添加文件...</strong> 选择源归档</li><li>选择 <strong>目标格式</strong></li><li>（可选）启用 <strong>转换后删除源文件</strong></li><li>点击 <strong>开始</strong></li></ol><h3 id="批量加密-1" tabindex="-1">批量加密 <a class="header-anchor" href="#批量加密-1" aria-label="Permalink to &quot;批量加密&quot;">​</a></h3><ol><li>前往 <strong>工具 → 批量加密</strong></li><li>点击 <strong>添加文件...</strong> 选择归档</li><li>输入 <strong>密码</strong></li><li>点击 <strong>加密</strong></li></ol><h2 id="高级功能" tabindex="-1">高级功能 <a class="header-anchor" href="#高级功能" aria-label="Permalink to &quot;高级功能&quot;">​</a></h2><h3 id="归档修复-1" tabindex="-1">归档修复 <a class="header-anchor" href="#归档修复-1" aria-label="Permalink to &quot;归档修复&quot;">​</a></h3><p>修复损坏或损坏的归档：</p><ol><li>选择损坏的归档</li><li>前往 <strong>工具 → 修复归档</strong></li><li>NueZip 会扫描头部、重建目录并修复数据块</li><li>查看修复结果</li></ol><h3 id="格式转换-1" tabindex="-1">格式转换 <a class="header-anchor" href="#格式转换-1" aria-label="Permalink to &quot;格式转换&quot;">​</a></h3><p>在格式之间转换归档：</p><ol><li>打开一个归档或选择一个文件</li><li>前往 <strong>文件 → 转换格式</strong></li><li>选择目标格式和压缩级别</li><li>（可选）删除原始文件</li><li>点击 <strong>转换</strong></li></ol><h3 id="密码管理器" tabindex="-1">密码管理器 <a class="header-anchor" href="#密码管理器" aria-label="Permalink to &quot;密码管理器&quot;">​</a></h3><p>NueZip 将归档密码安全地存储在你本地的钥匙串中：</p><ol><li>前往 <strong>工具 → 密码管理器</strong></li><li>查看所有已保存的密码</li><li>添加、编辑或删除条目</li><li>打开匹配的加密归档时，密码会自动应用</li></ol><h3 id="性能基准测试-1" tabindex="-1">性能基准测试 <a class="header-anchor" href="#性能基准测试-1" aria-label="Permalink to &quot;性能基准测试&quot;">​</a></h3><p>测试你系统的压缩性能：</p><ol><li>前往 <strong>工具 → 性能基准测试</strong></li><li>选择一个测试文件（或使用默认文件）</li><li>点击 <strong>测试</strong></li><li>查看结果，包括压缩/解压速度和评级</li></ol><h3 id="归档搜索-1" tabindex="-1">归档搜索 <a class="header-anchor" href="#归档搜索-1" aria-label="Permalink to &quot;归档搜索&quot;">​</a></h3><p>在归档中查找文件：</p><ol><li>打开一个归档</li><li>按下 <code>Cmd+F</code> 或点击搜索图标</li><li>输入文件名，可选择是否区分大小写或全字匹配</li><li>浏览搜索结果并点击以导航</li></ol><h2 id="键盘快捷键" tabindex="-1">键盘快捷键 <a class="header-anchor" href="#键盘快捷键" aria-label="Permalink to &quot;键盘快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>操作</th></tr></thead><tbody><tr><td><code>Cmd+O</code></td><td>打开归档</td></tr><tr><td><code>Cmd+N</code></td><td>新建归档</td></tr><tr><td><code>Cmd+E</code></td><td>解压</td></tr><tr><td><code>Cmd+F</code></td><td>在归档中查找</td></tr><tr><td><code>Cmd+,</code></td><td>打开设置</td></tr><tr><td><code>Cmd+W</code></td><td>关闭窗口</td></tr><tr><td><code>Cmd+Q</code></td><td>退出应用</td></tr><tr><td><code>Cmd+↑</code></td><td>向上一级</td></tr><tr><td><code>Cmd+→</code></td><td>前进</td></tr></tbody></table><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h2><p>通过 <strong>NueZip → 设置</strong> 或按下 <code>Cmd+,</code> 访问设置：</p><ul><li><strong>通用</strong>：语言、登录时启动、外观主题</li><li><strong>压缩</strong>：默认格式、压缩级别、拆分大小</li><li><strong>解压</strong>：默认目标、包裹行为、冲突处理</li><li><strong>文件夹访问</strong>：管理文件夹权限和书签</li><li><strong>高级</strong>：硬件加速、线程数、临时目录</li><li><strong>隐私</strong>：数据收集偏好</li></ul>',85)])])}const b=i(r,[["render",e]]);export{u as __pageData,b as default};
